import { describe, expect, it } from "vitest";
import { createGeospatialCamera, setGeospatialOrientation } from "@babylonjs/lite";
import { tiltGlobeCamera } from "./globe-tilt.ts";

const R = 6371000;

function viewErr(cam: any) {
    // direction from eye to centre must equal lookAt
    const c = cam.center, p = cam.position;
    const d = [c.x - p.x, c.y - p.y, c.z - p.z];
    const len = Math.hypot(...d);
    const l = cam._lookAt;
    return Math.hypot(d[0] / len - l.x, d[1] / len - l.y, d[2] / len - l.z);
}

describe("tiltGlobeCamera", () => {
    for (const pitch of [0.1, 0.6, 1.2]) {
        it(`tilts a fresh (zoomed-out) camera to ${pitch}`, () => {
            const cam = createGeospatialCamera({ planetRadius: R });
            const c0 = { ...cam.center }, y0 = cam.yaw, r0 = cam.radius;
            tiltGlobeCamera(cam, pitch);
            expect(cam.pitch).toBeCloseTo(pitch, 9);
            expect(cam.radius).toBe(r0);
            expect(cam.yaw).toBe(y0);
            expect(cam.center).toEqual(c0);
            expect(viewErr(cam)).toBeLessThan(1e-9);
        });
        it(`holds ${pitch} while zooming in and out`, () => {
            const cam = createGeospatialCamera({ planetRadius: R });
            tiltGlobeCamera(cam, pitch);
            for (const r of [R * 10, R * 3, R * 1.5, 50, R * 2.5, R * 4]) {
                setGeospatialOrientation(cam, { radius: r });
                expect(cam.pitch).toBeCloseTo(pitch, 9);
                expect(viewErr(cam)).toBeLessThan(1e-9);
            }
        });
    }
    it("keeps heading after a non-zero yaw", () => {
        const cam = createGeospatialCamera({ planetRadius: R });
        setGeospatialOrientation(cam, { yaw: 0.7, radius: R * 2 });
        const y0 = cam.yaw;
        tiltGlobeCamera(cam, 0.8);
        expect(cam.yaw).toBeCloseTo(y0, 12);
        expect(cam.pitch).toBeCloseTo(0.8, 9);
    });
});
EOF
